/** @param {string} [language] UI language from settings (en, zh, es, fr, de, ru, pt); supplier checklist is localized. */
export function getQuestionnaire(standard, auditType, language = 'en') {
  if (standard === 'IATF 16949:2016' || standard === 'ISO 9001:2015') {
    return buildSupplierSmqQuestionnaireForLanguage(language)
  }
  if (DETAILED_QUESTIONNAIRES[standard]) return DETAILED_QUESTIONNAIRES[standard];
  if ((auditType||"").includes("Financial")) return DEFAULT_Q["Financial"];
  if ((auditType||"").includes("Cyber")) return DEFAULT_Q["Cybersecurity / IT"];
  return DEFAULT_Q["Manufacturing / Quality"];
}
export function getQuestionnaireVerdictPreset(standard) {
  if (standard === 'IATF 16949:2016' || standard === 'ISO 9001:2015') return VERDICT_PRESET_SUPPLIER_RU_SCORE
  return VERDICT_PRESET_ISO_CONFORMANCE
}
export function getTotalQuestions(q) { return (q||[]).reduce((s,sec)=>s+(sec.questions?.length||0),0); }
